  | { success: true; value: T }
  | { success: false; error: E };

export async function processPremiumPayment(
  userId: string,
  payment: PaymentDetails,
  tier: 'premium' | 'enterprise'
): Promise<Result<void, PaymentError>> {
  if (!validatePaymentDetails(payment)) {
    return { 
      success: false, 
      error: new PaymentError('INVALID_PAYMENT_DETAILS', 'Invalid payment details')
    };
  }

  const chargeResult = await chargeCard(payment, amount);

  if (!chargeResult.success) {
    return { success: false, error: chargeResult.error };
  }

  await upgradeUserSubscription(userId, tier);
  return { success: true, value: undefined };
}

